class UnionFind {
    private final int[] parent, size;
    private int parts;                          // 集合的个数

    public UnionFind(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;                      // 一开始每个点自己是根
            size[i] = 1;
        }
        parts = n;
    }

    public int find(int x) {
        while (parent[x] != x) {                // 往上走到根
            parent[x] = parent[parent[x]];      // 路径压缩：指向爷爷
            x = parent[x];
        }
        return x;
    }

    public boolean unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) {                         // 已经在一个集合里
            return false;
        }
        if (size[ra] < size[rb]) {              // 小树挂到大树下面
            int t = ra; ra = rb; rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
        parts--;
        return true;
    }

    public boolean connected(int a, int b) {
        return find(a) == find(b);
    }

    public int count() {
        return parts;
    }
}

